SELECT account_id,
       AVG(CASE WHEN type = 'PRIJEM' THEN amount ELSE -amount END) AS mean_signed_amount,
       COUNT(*) AS txn_count,
       COUNT(*) / ((SELECT COUNT(*) FROM trans) * 1.0 / (SELECT COUNT(DISTINCT account_id) FROM trans)) AS ratio
FROM trans
GROUP BY account_id
ORDER BY ratio DESC
LIMIT 10;
SELECT AVG(cnt) FROM (SELECT COUNT(*) AS cnt FROM trans GROUP BY account_id);
